def verifier(assign):
    import math
    # Validate domains
    try:
        alpha = assign['alpha']
        beta = assign['beta']
        gamma = assign['gamma']
    except Exception:
        # Missing slots
        return (False, None)
    if not (isinstance(alpha, int) and alpha > 0):
        # alpha must be positive integer
        return (False, None)
    if not (isinstance(beta, (int, float)) and isinstance(gamma, (int, float))):
        return (False, None)
    if not (beta > 0 and gamma > 0):
        return (False, None)
    # Check trig denominator is safely nonzero
    denom = 2.0*math.cos(alpha) + math.cos(3.0*alpha)
    if abs(denom) < 1e-12:
        # extremely unlikely with integer radians, but reject if happens
        return (False, None)

    # Solve for mu via KKT/Lagrange system
    def F(mu):
        if mu <= 0:
            return None
        t = (gamma/(3.0*mu))**0.5
        Q = 3.0*mu/gamma - 2.0*t
        if Q <= 0:
            return None
        r2 = (3.0*mu - 2.0*gamma*t)/beta
        if r2 <= 0:
            return None
        r = r2**0.5
        D = 3.0*mu*r*r - 2.0*beta*r
        if D <= 0:
            return None
        c = alpha/(D**0.5)
        f = (alpha*alpha) * r * c + beta * (r*r) * (c**3) + gamma * (c**2) * (t * c)
        g = alpha**3 + (r**3 + 1.0 + t**3) * (c**3)
        mu_cand = f/g
        return mu_cand - mu

    # Bracket and bisection
    low = gamma*1e-4
    high = gamma*100.0
    fl = F(low)
    fh = F(high)
    expand_count = 0
    while (fl is None or fh is None) and expand_count < 12:
        low /= 10.0
        high *= 10.0
        fl = F(low)
        fh = F(high)
        expand_count += 1
    if fl is None or fh is None:
        return (False, None)

    # Scan for a sign change on a log grid
    prev_mu = low
    prev_val = fl
    found = False
    mu_star = None
    ngrid = 300
    for i in range(1, ngrid+1):
        mu = low * (high/low)**(i/ngrid)
        val = F(mu)
        if val is None:
            continue
        if prev_val is not None and val*prev_val < 0:
            # Bisection
            a = prev_mu
            b = mu
            fa = prev_val
            fb = val
            for _ in range(150):
                m = 0.5*(a+b)
                fm = F(m)
                if fm is None:
                    # shrink interval
                    b = 0.5*(a+b)
                    continue
                if abs(fm) < 1e-16:
                    a = b = m
                    fa = fb = fm
                    break
                if fa*fm <= 0:
                    b = m
                    fb = fm
                else:
                    a = m
                    fa = fm
                if abs(b-a) < 1e-18:
                    break
            mu_star = 0.5*(a+b)
            found = True
            break
        prev_mu = mu
        prev_val = val
    if not found or mu_star is None or mu_star <= 0:
        return (False, None)

    final_answer_value = 5.0 * mu_star
    # Difficulty enforcement: ensure nontrivial magnitude
    if final_answer_value < 0.8:
        return (False, None)

    # Format the boxed answer with sufficient precision (10 decimal places)
    boxed = f"### The final answer is: \\boxed{{{final_answer_value:.10f}}}"
    return (True, boxed)
